-- 세트 107: k8s 장애 읽기 입문: Pod 상태 한마디씩
-- 쉬운 입문 세트(docs/specs/spec_friendly_audit.md). 정답·해설은 서버만 안다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (107, 1, '정상 Pod 의 상태', '`kubectl get pods` 의 STATUS 열에서 **정상적으로 실행 중**인 Pod 는 `___` 라고 표시됩니다.', '"달리는 중"이라는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["Running", "Pending", "Error", "Done"]', NULL, '`Running` 이면 컨테이너가 실행 중이에요. 처음 보는 상태 단어가 나와도 하나씩 알면 괜찮아요. 천천히 가 봐요.', '[0]', 'STATUS: {0}', NULL, NULL),
  (107, 2, 'Pending 은 무슨 뜻일까?', 'Pod 가 오래 `Pending` 입니다. 가장 알맞은 뜻은 무엇일까요?', 'pending = "대기 중". 아직 시작하지 못했어요.', NULL, NULL, '[]', 'choice', '["정상적으로 끝났다", "이미지가 삭제됐다", "아직 어떤 노드에서도 시작하지 못하고 기다리는 중 (자원 부족, 볼륨 대기 등)", "노드가 폭발했다"]', 2, '맞아요! Pending 은 "시작을 못 하고 기다리는 중"이에요. 이유는 `describe` 의 Events 에 적혀 있어요.', NULL, NULL, NULL, NULL),
  (107, 3, '상태 이름 짝 맞추기', '상태 이름을 알맞은 설명에 연결해 보세요. ① 이미지를 받아 오지 못해 재시도 중 ② 컨테이너가 켜졌다 꺼지기를 반복', '이미지 문제는 Pull(받기), 계속 죽고 재시작은 Crash.', NULL, NULL, '[]', 'fill', '["ImagePullBackOff", "CrashLoopBackOff", "Pending", "Completed"]', NULL, '`ImagePullBackOff` 는 이미지 이름·태그가 틀렸거나 받을 수 없을 때, `CrashLoopBackOff` 는 프로그램이 시작하자마자 죽을 때 나와요. 이름이 길어도 뜻은 단순해요.', '[0, 1]', '① {0}
② {1}', NULL, NULL),
  (107, 4, '이미지 태그를 잘못 썼을 때', '`nginx:1.99.99` 처럼 **없는 태그**로 배포했습니다. Pod 는 어떤 상태가 될까요?', '이미지를 받는 데 실패하는 문제입니다.', NULL, NULL, '[]', 'choice', '["`Completed`", "`Running` 이지만 느리다", "`Terminating`", "`ImagePullBackOff` (또는 `ErrImagePull`)"]', 3, '정확해요! 없는 태그는 이미지를 받지 못해 `ErrImagePull` → `ImagePullBackOff` 가 됩니다. 태그를 고치면 해결돼요.', NULL, NULL, NULL, NULL),
  (107, 5, '막힌 Pod 를 살펴보는 순서', '시작하지 못하는 Pod 를 처음 만났을 때 **봐야 할 순서**를 놓아 보세요.', '목록으로 상태를 보고, 자세히 보고, 필요하면 로그를 보고, 고친 뒤 확인합니다.', NULL, NULL, '[]', 'order', '["`kubectl describe pod` 맨 아래 Events 에서 이유를 읽는다", "고친 뒤 다시 `get pods` 로 Running 이 되었는지 확인한다", "`kubectl get pods` 로 STATUS 를 확인한다", "필요하면 `kubectl logs` 로 프로그램이 남긴 메시지를 본다"]', NULL, '**get(상태) → describe(Events) → logs(프로그램 메시지) → 고치고 다시 확인** 입니다. 이 순서가 몸에 배면 어떤 장애도 차분히 시작할 수 있어요.', '[2, 0, 3, 1]', NULL, NULL, NULL),
  (107, 6, 'describe 에서 어디를 볼까?', '`kubectl describe pod` 의 출력은 깁니다. 시작 실패 이유를 가장 빨리 찾으려면 어디를 볼까요?', '사건 기록이 쌓이는 곳, 맨 아래에 있어요.', NULL, NULL, '[]', 'choice', '["맨 위 이름", "맨 아래 `Events` 목록", "`Labels` 줄", "`IP` 줄"]', 1, '맞아요! `Events` 에 "무슨 일이 있었는지"가 시간순으로 적혀 있어요. `Failed to pull image` 같은 문장이 바로 단서입니다.', NULL, NULL, NULL, NULL),
  (107, 7, '조사 명령 채우기', '① Pod `web-1` 의 상세 정보와 사건 기록, ② Pod `web-1` 의 프로그램 로그를 보는 명령입니다.', '자세히 설명 = describe, 기록 = logs.', NULL, NULL, '[]', 'fill', '["describe", "logs", "delete", "apply"]', NULL, '`describe` 는 쿠버네티스가 아는 정보(Events 포함), `logs` 는 컨테이너 프로그램이 출력한 내용을 보여 줘요. 둘이 서로 다른 단서를 줍니다.', '[0, 1]', 'kubectl {0} pod web-1
kubectl {1} web-1', NULL, NULL),
  (107, 8, 'CrashLoopBackOff 와 로그', 'CrashLoopBackOff 인 Pod 의 `kubectl logs` 가 비어 있습니다. 직전에 죽은 컨테이너의 로그를 보려면 어떤 옵션을 쓸까요?', '"이전"이라는 영어 단어입니다.', NULL, NULL, '[]', 'choice', '["`kubectl logs Pod이름 --delete`", "`kubectl get logs`", "`kubectl logs Pod이름 --previous`", "`kubectl restart`"]', 2, '좋아요! 새로 시작한 컨테이너는 아직 로그가 없을 수 있어요. `--previous`(`-p`)는 방금 죽은 컨테이너의 로그를 보여 줍니다.', NULL, NULL, NULL, NULL),
  (107, 9, 'Pod 를 직접 고쳐도 될까?', 'Deployment 가 만든 Pod 의 이미지 태그가 틀렸습니다. 올바른 고치는 대상은 무엇일까요?', 'Pod 는 지워지고 다시 만들어지는 존재예요.', NULL, NULL, '[]', 'choice', '["Pod 하나만 계속 수정한다", "노드를 재부팅한다", "네임스페이스를 삭제한다", "Deployment (그러면 Pod 가 새 설정으로 다시 만들어진다)"]', 3, '맞아요! Pod 는 Deployment 가 계속 만들어 주는 "결과물"이에요. 설계도(Deployment)를 고쳐야 새 Pod 가 제대로 만들어져요.', NULL, NULL, NULL, NULL),
  (107, 10, '이미지 태그를 고치는 순서', 'Deployment 의 이미지 태그를 고쳐 정상화하는 흐름을 놓아 보세요.', '원인 확인 → 수정 → 결과 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl rollout status` 나 `get pods` 로 Running 인지 확인한다", "`describe` 로 이미지 받기 실패(태그 오류)를 확인한다", "`kubectl set image` 로 Deployment 의 이미지를 올바른 태그로 바꾼다"]', NULL, '**원인 확인 → set image 로 수정 → rollout 확인** 입니다. 한 번에 하나만 고치고 결과를 확인하는 것이 안전해요.', '[1, 2, 0]', NULL, NULL, NULL);
